tools.example:
model.component("comp1").geom("geom1").create("b1", "BezierPolygon");
model.component("comp1").geom("geom1").feature("b1").set("type", "solid");
model.component("comp1").geom("geom1").feature("b1").set("degree", new int[]{1, 2, 1});
model.component("comp1").geom("geom1").feature("b1").set("p", new String[][]{{"0","1","1","0","0"}, {"0","0","0.5","1","0"}});
model.component("comp1").geom("geom1").feature("b1").set("w", new String[]{"1","1","1","1","1","1"});

GeomSequence g = model.component("comp1").geom("geom1");
g.create("ic1", "InterpolationCurve");
g.feature("ic1").set("type", "solid");
g.feature("ic1").set("table", new double[][]{{0,0}, {1,0}, {1.2,0.5}, {0.5,1}, {0,0.8}});
g.feature("ic1").set("rtol", 1e-3);
g.run();

model.component("comp1").geom("geom1").create("spl1", "Split");
model.component("comp1").geom("geom1").feature("spl1").selection("input").set("imp1");
// resulting objects are named spl1(1), spl1(2), ...

// after building the link in the GUI
model.component("comp1").geom("geom1").feature("cad1").set("paramname", new String[]{"D1@Sketch1"});
model.component("comp1").geom("geom1").feature("cad1").set("paramvalue", new String[]{"w"});
model.param().set("w", "25[mm]");
model.component("comp1").geom("geom1").run();   // synchronises with SOLIDWORKS

model.component("comp1").geom("geom1").measure().selection().init(3);
model.component("comp1").geom("geom1").measure().selection().set("fin", new int[]{1});
double V = model.component("comp1").geom("geom1").measure().getVolume();
% MATLAB: mphmeasure(model, 'geom1', 'domain', 'selection', 1)

GeomSequence g = model.component("comp1").geom("geom1");
g.lengthUnit("mm");
g.geomRep("cadps");
g.run();
int ndom = g.getNDomains();
int nbnd = g.getNBoundaries();
